// Cross-source / freshness cases. Synthetic role-word documents only.
import { doc, day, NOW, DAY } from "./lib.mjs";
const fresh = (name, kind) => ({ name, kind, lastIngestDaysAgo: 0, expectedSeconds: 86400, sweepDaysAgo: 1 });
const HEALTHY = [fresh("mail", "gmail"), fresh("files", "drive"), fresh("texts", "imessage"), fresh("meetings", "upload")];
const withSrc = (over) => HEALTHY.map(s => over[s.name] ? { ...s, ...over[s.name] } : s);
// doc number the real prompt assigned to a title
export const num = (all, title) => { const m = new RegExp(`\\[(\\d+)\\] \\((?:(?!\\\\n\\[\\d).)*?\\) ${title.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`).exec(all); return m ? Number(m[1]) : 0; };
const ok = (all, titles) => ({ supported: true, complete: true, evidence: titles.map(t => num(all, t)).filter(Boolean), reason: "direct support" });
// last week (Mon..Sun, UTC): a day inside it, and a day just before it
const dow = (new Date(NOW).getUTCDay() + 6) % 7; // 0 = Monday
const insideLastWeek = dow + 4;   // last week's Thursday
const beforeLastWeek = dow + 9;   // the Saturday before last week
const filler = (n) => Array.from({ length: n }, (_, i) => `Section ${i + 1}. General obligations of the parties regarding scheduling, packaging, access to the loading area and routine notices are set out in this section in ordinary terms.`).join("\n");

